import {profiles,rules,eligible,mockML,mockEvidence,mockContext,referral} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let profile={...profiles[0]},mode='mock',view='workbench',files=[],run=null,busy=false,controller=null,apiStatus=null;
const events=[],stages=[['intake','Application & input guardrails'],['ml','Historical ML risk screening'],['evidence','Vision LLM · evidence understanding'],['context','Internal, external & knowledge retrieval'],['reason','Reasoning harness · bounded revision'],['verify','Output guardrails & business rules'],['decision','Assessment outcome']];
function log(action,detail){events.unshift({time:new Date().toISOString(),profile:profile.name,mode,action,detail});}
function badge(s,color='blue'){return `<span class="badge ${color}">${esc(s)}</span>`}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function reset(){run=null;log('Assessment invalidated','Inputs or mode changed.');}
function render(){const labels={workbench:'Assessment studio',flow:'Hybrid architecture',rules:'Rules & guardrails',settings:'Local API setup',audit:'Audit trail'};$('#crumb').textContent=labels[view];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#app').innerHTML=view==='workbench'?studio():view==='flow'?architecture():view==='rules'?rulesView():view==='settings'?settings():audit();bind()}
function options(values,current){return values.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('')}
function studio(){return `<div class="page-title"><div><span class="eyebrow">HYBRID AI UNDERWRITING</span><h1>Fast when simple. Thorough when complex.</h1><p class="muted">ML straight-through processing, with a guarded Vision LLM path for exceptions.</p></div><div class="mode-switch" role="group" aria-label="Assessment mode"><button data-mode="mock" class="${mode==='mock'?'active':''}" ${busy?'disabled':''}>Mock AI demo</button><button data-mode="local" class="${mode==='local'?'active':''}" ${busy?'disabled':''}>Local API testing</button></div></div><div class="mode-notice">${mode==='mock'?'● SIMULATION · Fictional profiles, scripted AI outputs and synthetic documents. Uploaded content is not analysed.':'● LOCAL API · Real model calls through your local runner. No silent fallback to mock results.'}</div><div class="hybrid-grid"><section class="panel profile-panel"><div class="section-heading"><h2>Customer profile</h2>${badge('01 · INPUT')}</div><label>Choose a demo journey<select id="profile" ${busy?'disabled':''}>${profiles.map(p=>`<option value="${p.id}" ${p.id===profile.id?'selected':''}>${p.name} — ${p.title}</option>`).join('')}</select></label><div class="profile-summary"><div class="person-avatar">${esc(profile.name.split(' ').map(s=>s[0]).join(''))}</div><div><h2>${esc(profile.name)}</h2><p>${esc(profile.occupation)} · ${profile.age} years</p></div></div><form id="profile-form"><fieldset ${busy?'disabled':''}><div class="form-grid"><label>Product<select name="product">${options(['Life','Medical'],profile.product)}</select></label><label>Age<input name="age" required type="number" min="18" max="100" value="${profile.age}"></label><label>Sex (demographic)<select name="sex">${options(['Male','Female','Not specified'],profile.sex)}</select></label><label>Occupation<input name="occupation" required maxlength="80" value="${esc(profile.occupation)}"></label><label>Cover (SGD)<input name="cover" required type="number" min="1000" max="10000000" step="1000" value="${profile.cover}"></label><label>BMI (declared)<input name="bmi" required type="number" min="10" max="70" step=".1" value="${profile.bmi}"></label><label>Smoking<select name="smoker"><option value="false" ${!profile.smoker?'selected':''}>Non-smoker</option><option value="true" ${profile.smoker?'selected':''}>Smoker</option></select></label><label>Medical history<select name="condition">${[['none','No declared conditions'],['controlled','Stable condition'],['complex','Complex history']].map(([v,t])=>`<option value="${v}" ${v===profile.condition?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="section-heading"><h3>Supporting documents</h3><span class="muted">${files.length} uploaded</span></div><label class="upload-zone">＋ Add medical reports or blood tests<input id="upload" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp" aria-label="Upload supporting documents"><small>PDF, PNG, JPEG, WebP · 10 MB each · 20 MB total · max 5 files</small></label><div class="file-list">${files.map((f,i)=>`<div><span>▤ ${esc(f.name)} <small>${(f.size/1024).toFixed(0)} KB</small></span><button type="button" data-remove="${i}" aria-label="Remove ${esc(f.name)}">×</button></div>`).join('')}</div>${mode==='mock'?`<label class="check"><input name="evidence" type="checkbox" ${profile.evidence?'checked':''}> Synthetic evidence complete</label><p class="micro">Sample medical report and blood test follow the scenario. Uploaded file content is not read.</p>`:'<p class="micro">Files are sent at execution through the local runner to your Vision LLM. Use test or de-identified records.</p>'}<button class="primary full" type="submit">${busy?'Assessment in progress…':run?'Re-run hybrid assessment ↻':'Run hybrid assessment →'}</button></fieldset></form>${busy?'<button class="secondary full" id="cancel">Cancel assessment</button>':''}</section><div class="assessment-column"><section class="panel pipeline-panel"><div class="section-heading"><div><span class="eyebrow">LIVE EXECUTION</span><h2>Assessment journey</h2></div>${badge(run?.route||'Ready',busy?'amber':'green')}</div><div class="pipeline">${stages.map(([id,title],i)=>{const s=run?.steps[id];return `<div class="pipeline-step ${s?.status||''}"><div class="stage-dot">${s?.status==='done'?'✓':s?.status==='skipped'?'–':s?.status==='error'?'!':String(i+1).padStart(2,'0')}</div><div class="stage-body"><div><strong>${title}</strong><span>${s?.status==='running'?'Running…':s?.status==='done'?'Complete':s?.status==='skipped'?'Skipped':s?.status==='error'?'Stopped':'Pending'}</span></div><p>${esc(s?.summary||stageHint(id))}</p>${s?.data?`<details><summary>Inspect step output</summary><pre>${esc(JSON.stringify(s.data,null,2))}</pre></details>`:''}</div></div>`}).join('')}</div></section>${resultView()}${!run?`<div class="path-preview"><div><span class="eyebrow">FAST PATH</span><h3>ML → standard acceptance</h3><p>High-confidence, in-distribution standard cases pass evidence and business gates.</p></div><div><span class="eyebrow">COMPLEX PATH</span><h3>Vision LLM → reviewed recommendation</h3><p>Exceptions enter evidence extraction, retrieval, bounded reasoning and verification.</p></div></div>`:''}</div></div>`}
function stageHint(id){return ({intake:'Validate customer inputs and document constraints.',ml:'Historical model classification, confidence and out-of-distribution checks.',evidence:'Read reports and images; extract findings and flag evidence gaps.',context:'Internal rules, RAG passages, knowledge relationships and external context.',reason:'Assess evidence against context; revise once if validation fails.',verify:'Check source attribution, output structure and mandatory referral rules.',decision:'Show outcome, reasons, supporting evidence and next actions.'})[id]}
function resultView(){if(!run?.result)return '';const r=run.result;return `<section class="panel result-panel"><div class="section-heading"><span class="eyebrow">ASSESSMENT RESULT</span>${badge(mode==='mock'?'Simulated result':'Local model result',mode==='mock'?'purple':'blue')}</div><div class="decision-banner">${badge(r.status,r.status==='Standard acceptance'?'green':r.status==='Failed'||r.status==='Cancelled'?'red':'amber')}<h2>${esc(r.headline)}</h2><p>${esc(r.explanation)}</p></div><h3>Reasons & explanations</h3>${r.reasons.map(t=>`<div class="reason-line"><span>↳</span><p>${esc(t)}</p></div>`).join('')}${r.sources?.length?`<h3 class="spaced">Evidence & source attribution</h3>${r.sources.map(s=>`<div class="source-card"><code>${esc(s.id)}</code><div><strong>${esc(s.title||s.source)}</strong><p>${esc(s.excerpt||s.text)}</p>${safeLink(s.url)}</div></div>`).join('')}`:''}<div class="note"><strong>Next action</strong><p>${esc(r.next)}</p></div>${r.review&&!busy?`<form id="review-form"><h3>Underwriter review</h3><label>Decision<select name="outcome"><option>Approve standard terms</option><option>Propose revised terms</option><option>Request further evidence</option><option>Postpone</option><option>Decline</option></select></label><label>Decision reason<textarea name="reason" required minlength="10" maxlength="1500" placeholder="Explain the evidence considered and any proposed terms."></textarea></label><button class="primary">Record human decision</button></form>`:''}${r.human?`<div class="note"><strong>Human decision: ${esc(r.human.outcome)}</strong><p>${esc(r.human.reason)}</p></div>`:''}<button class="secondary" id="export-result">Download assessment JSON ↓</button></section>`}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}catch{return ''}}
function architecture(){return `<div class="page-title"><div><span class="eyebrow">TWO PATHS, ONE CONTROLLED PROCESS</span><h1>Hybrid intelligence. Explicit decision gates.</h1><p class="muted">Historical ML screens standard cases. Vision LLM reasoning handles exceptions.</p></div></div><div class="panel flow-panel"><div class="flow-track"><div class="flow-node"><span class="step-number">OFFLINE · MODEL DEVELOPMENT</span><h3>Historical applications & outcomes</h3><p>Curated training data → validation and calibration → model registry. Training is outside this demo; connect your deployed model.</p></div><div class="flow-node"><span class="step-number">01 · INTAKE</span><h3>Profile + supporting evidence</h3><p>Demographics, cover, declarations, medical reports and blood tests. Validate inputs and evidence availability.</p></div><div class="flow-node"><span class="step-number">02 · ML SCREENING</span><h3>Standard-case classifier</h3><p>Class, calibrated confidence and OOD checks. API errors enter the complex path, never automatic approval.</p></div></div><div class="routing">STP GATE<span>Standard + confidence ≥ 0.95 + calibrated + in-distribution + complete evidence + business rules pass</span></div><div class="architecture-paths"><div class="fast-lane"><span class="eyebrow">PASS · STRAIGHT-THROUGH</span><h2>Standard acceptance</h2><p>Record model version, reasons and gate results. Skip expensive reasoning layers.</p></div><div class="complex-lane"><span class="eyebrow">EXCEPTION · DEEPER ASSESSMENT</span><h2>Guarded Vision LLM reasoning</h2><div class="mini-stages"><div><strong>1. Understand evidence</strong><p>Vision extraction with source IDs, uncertainty and evidence gaps.</p></div><div><strong>2. Retrieve context</strong><p>Internal APIs, external data, RAG, OKF / knowledge graph adapters and an optional internet search service.</p></div><div><strong>3. Execute the harness</strong><p>Structured reasoning → citation checks → one revision maximum → guardrails and business rules.</p></div><div><strong>4. Explain & refer</strong><p>Evidence-linked recommendation, missing information and human decision.</p></div></div></div></div></div>`}
function rulesView(){return `<div class="page-title"><div><span class="eyebrow">DEMO POLICY · HYBRID-1.0</span><h1>Make every gate inspectable.</h1><p class="muted">Illustrative controls, not approved insurer or actuarial rules.</p></div></div><div class="panel table-wrap"><table><thead><tr><th>Control</th><th>Layer</th><th>Behaviour</th></tr></thead><tbody>${rules.map(r=>`<tr><td><code>${r[0]}</code></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div><div class="note"><strong>Conservative decision authority in local mode</strong><p>No trained model is bundled. Missing ML integration enters the complex path. Vision LLM output cannot issue a policy or silently approve a referral. Source checks and instruction isolation are not a complete prompt-injection defence.</p></div>`}
function settings(){const local=['localhost','127.0.0.1','[::1]'].includes(location.hostname);return `<div class="page-title"><div><span class="eyebrow">BRING YOUR OWN MODELS</span><h1>Connect your local testing environment.</h1><p class="muted">Keep API keys and service addresses in the Python runner’s environment.</p></div></div><div class="panel setup-panel"><h2>Local runner + your model APIs</h2><p>The hosted demo runs mock mode. For real document testing, open this repository’s local runner on your machine. It serves the same interface and forwards requests to your configured APIs.</p><pre>pip install -r requirements.txt\nexport UW_LLM_BASE_URL=http://localhost:8000/v1\nexport UW_LLM_MODEL=your-vision-model\n# Optional: UW_LLM_API_KEY, UW_ML_URL, UW_CONTEXT_URL\npython server.py\n# Open http://127.0.0.1:8080</pre><p>Use a Vision LLM endpoint supporting OpenAI-compatible chat completions with image inputs. PDF pages are rendered as images. ML and context adapters have documented JSON contracts in the repository.</p><div class="note"><strong>${local?'Local address detected':'You are viewing the hosted demo'}</strong><p>${local?'Check the runner before starting a real assessment.':'Real mode requires the local runner. This hosted page will not access your private network.'}</p></div><button class="primary" id="health" ${!local?'disabled':''}>Check local connection</button>${apiStatus?`<pre>${esc(JSON.stringify(apiStatus,null,2))}</pre>`:''}<div class="setup-grid"><div><h3>Historical ML adapter</h3><p>Returns classification, calibrated confidence, OOD, model version and evidence completeness. Without it, STP is disabled.</p></div><div><h3>Vision LLM</h3><p>Reads images or PDF pages and generates an evidence-linked recommendation. Invalid responses stop or refer the assessment.</p></div><div><h3>Context adapter</h3><p>Connect internal / external data, RAG, OKF, graphs or web search. Return typed, attributable excerpts. No live retrieval is claimed when absent.</p></div><div><h3>Data handling</h3><p>Uploads stay in browser memory until execution and are processed in runner memory. Model and retrieval services may retain requests under their own configuration.</p></div></div></div>`}
function audit(){return `<div class="page-title"><div><span class="eyebrow">SESSION EVENTS</span><h1>Follow the evidence trail.</h1><p class="muted">Events reset on refresh. Download a record of this session.</p></div><button id="export-audit" class="secondary">Export JSON ↓</button></div><div class="panel table-wrap"><table><thead><tr><th>Time</th><th>Profile / mode</th><th>Event</th><th>Detail</th></tr></thead><tbody>${events.length?events.map(e=>`<tr><td>${new Date(e.time).toLocaleTimeString()}</td><td>${esc(e.profile)}<br>${e.mode}</td><td>${esc(e.action)}</td><td>${esc(typeof e.detail==='string'?e.detail:JSON.stringify(e.detail))}</td></tr>`).join(''):'<tr><td colspan="4">Run an assessment to begin the audit trail.</td></tr>'}</tbody></table></div>`}
function download(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function bind(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;reset();render()});if($('#profile'))$('#profile').onchange=e=>{profile={...profiles.find(p=>p.id===e.target.value)};files=[];reset();render()};if($('#upload'))$('#upload').onchange=e=>{const add=[...e.target.files];if(files.length+add.length>5||add.some(f=>f.size>10*1024*1024||!['application/pdf','image/png','image/jpeg','image/webp'].includes(f.type))||[...files,...add].reduce((a,f)=>a+f.size,0)>20*1024*1024){toast('Use up to 5 PDF or image files, 10 MB each and 20 MB total.');e.target.value='';return}saveProfile();files.push(...add);reset();render()};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{saveProfile();files.splice(+b.dataset.remove,1);reset();render()});if($('#profile-form')){const form=$('#profile-form');form.onchange=e=>{if(e.target.id==='upload')return;if(form.reportValidity()){saveProfile();reset();render()}};form.onsubmit=e=>{e.preventDefault();saveProfile();start()}}if($('#cancel'))$('#cancel').onclick=()=>controller.abort();if($('#health'))$('#health').onclick=async()=>{try{apiStatus=await api('health',null)}catch(e){apiStatus={error:e.message}}render()};if($('#review-form'))$('#review-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),reason=String(f.get('reason')).trim();if(reason.length<10){toast('Record at least 10 characters of reasoning.');return}run.result.human={outcome:f.get('outcome'),reason};run.result.review=false;log('Human decision',run.result.human);render()};if($('#export-result'))$('#export-result').onclick=()=>download({...run,profile,mode,files:files.map(f=>({name:f.name,size:f.size}))},'hybrid-assessment.json');if($('#export-audit'))$('#export-audit').onclick=()=>download(events,'hybrid-audit.json')}
function saveProfile(){const form=$('#profile-form');if(!form)return;const f=new FormData(form);Object.assign(profile,{product:f.get('product'),age:+f.get('age'),sex:f.get('sex'),occupation:f.get('occupation'),cover:+f.get('cover'),bmi:+f.get('bmi'),smoker:f.get('smoker')==='true',condition:f.get('condition')});if(mode==='mock')profile.evidence=f.get('evidence')==='on'}
async function api(path,body,signal){if(!['localhost','127.0.0.1','[::1]'].includes(location.hostname))throw Error('Open the local runner at http://127.0.0.1:8080 for real API testing. See Local API setup.');const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:signal?AbortSignal.any([signal,AbortSignal.timeout(150000)]):AbortSignal.timeout(150000)});let d;try{d=await r.json()}catch{throw Error('The local Python runner is not available at this address.')}if(!r.ok)throw Error(d.error||'Local API request failed');return d}
async function stage(id,fn){run.steps[id]={status:'running',summary:stageHint(id)};render();try{controller.signal.throwIfAborted();if(mode==='mock')await new Promise((resolve,reject)=>{const t=setTimeout(resolve,600);controller.signal.addEventListener('abort',()=>{clearTimeout(t);reject(new DOMException('Cancelled','AbortError'))},{once:true})});const d=await fn();controller.signal.throwIfAborted();run.steps[id]={status:'done',summary:d.summary,data:d.data};log(stages.find(s=>s[0]===id)[1],d.summary);render();return d.data}catch(e){run.steps[id]={status:'error',summary:e.message};throw e}}
async function fileData(){return Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,type:f.type,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('Could not read file '+f.name));reader.readAsDataURL(f)})))}
async function start(){if(busy)return;busy=true;controller=new AbortController();run={started:new Date().toISOString(),route:'Screening',steps:{},result:null};render();try{await stage('intake',async()=>{if(mode==='local'){await api('health',null,controller.signal);if(!files.length)throw Error('Upload at least one medical report or image for local testing.')}return {summary:'Inputs validated. '+(mode==='mock'?'Synthetic evidence selected.':files.length+' documents ready.'),data:{profile,documents:files.map(f=>({name:f.name,size:f.size})),mode}}});const ml=await stage('ml',async()=>{const d=mode==='mock'?mockML(profile):await api('ml',{profile,documents:await fileData()},controller.signal);return {summary:d.available?`Model ${d.model}: ${d.standard?'standard':'non-standard'}, confidence ${Math.round(d.confidence*100)}%, ${d.ood?'out-of-distribution':'in-distribution'}.`:'ML unavailable → guarded reasoning. '+(d.error||''),data:d}});const complete=mode==='mock'?profile.evidence:ml.evidence_complete===true;const stp=eligible(profile,ml,complete);if(stp){run.route='ML · straight-through';for(const id of ['evidence','context','reason'])run.steps[id]={status:'skipped',summary:'STP gate passed; complex reasoning not required.'};await stage('verify',async()=>({summary:'Standard class, calibration, confidence, OOD, evidence and referral gates passed.',data:{confidence:ml.confidence,threshold:.95,evidence_complete:complete,business_rules_passed:true,model:ml.model}}));await stage('decision',async()=>{run.result={status:'Standard acceptance',headline:'Eligible for straight-through processing',explanation:'The ML result and all configured STP gates passed.',reasons:[`Standard classification at ${Math.round(ml.confidence*100)}% model confidence.`,'Model reports calibration and an in-distribution application.',mode==='mock'?'Synthetic evidence is marked complete.':'Evidence completeness was certified by the ML adapter; Vision LLM analysis was skipped.','No mandatory business-rule referral matched.'],next:'Policy issuance handoff only; no policy is issued.',review:false};return {summary:'Standard acceptance recorded with gate results.',data:run.result}})}else{run.route='Vision LLM · complex path';const docs=mode==='local'?await fileData():[];const evidence=await stage('evidence',async()=>{const d=mode==='mock'?mockEvidence(profile,files):await api('evidence',{profile,documents:docs},controller.signal);return {summary:d.complete?'Evidence extracted with source attribution.':'Evidence gaps detected; automatic acceptance blocked.',data:d}});const context=await stage('context',async()=>{const d=mode==='mock'?mockContext():await api('context',{profile,findings:evidence.findings},controller.signal);return {summary:mode==='mock'?'Simulated internal, knowledge, external and web sources.':d.sources.length?`${d.sources.length} attributable sources retrieved.`:'No context adapter connected; enrichment unavailable.',data:d}});const reason=await stage('reason',async()=>{const d=mode==='mock'?{recommendation:evidence.complete?'refer':'request_evidence',explanation:evidence.complete?'The application did not satisfy the strict ML fast-path gate. Evidence-led review is required.':'A supporting report is outstanding, so a reliable assessment cannot be completed.',reasons:[profile.scenario==='ml_error'?'ML service failure triggered fallback.':referral(profile)?'Declared risk or coverage requires business-rule referral.':'STP gate did not pass.',evidence.findings[0].text],citations:['DOC-1','INT-1'],missing_information:evidence.complete?[]:['Complete medical report'],iterations:1,validation_errors:[],note:'Scripted reasoning, not a live LLM response.'}:await api('reason',{profile,evidence,context,ml},controller.signal);return {summary:`Structured recommendation: ${d.recommendation}. Harness iterations: ${d.iterations}.`,data:d}});const verified=await stage('verify',async()=>{const d=mode==='mock'?{passed:true,decision:evidence.complete?'refer':'request_evidence',checks:['Schema valid','Source IDs valid','No autonomous complex-case approval'],warnings:['Illustrative controls only; no live safety model used.']}:await api('verify',{profile,evidence,context,reason},controller.signal);return {summary:d.passed?'Output validated; human review retained.':'Output failed verification; human review required.',data:d}});await stage('decision',async()=>{run.result={status:verified.decision==='request_evidence'?'Awaiting evidence':'Manual review',headline:verified.decision==='request_evidence'?'Request further supporting evidence':'An explained recommendation, ready for review',explanation:reason.explanation,reasons:[...reason.reasons,...(reason.missing_information||[]).map(x=>'Missing: '+x),...(!verified.passed?['Verification did not pass; do not rely on the recommendation.']:[])],sources:[...evidence.findings,...context.sources].filter(s=>(reason.citations||[]).includes(s.id)),next:verified.decision==='request_evidence'?'Obtain missing evidence and run a fresh assessment.':'Review evidence and record a human decision. No autonomous complex-case approval.',review:true};return {summary:'Assessment completed with reasons and next actions.',data:run.result}})}log('Assessment completed',run.route)}catch(e){const cancelled=e.name==='AbortError';run.result={status:cancelled?'Cancelled':'Failed',headline:cancelled?'Assessment cancelled':'Assessment stopped safely',explanation:cancelled?'No approval has been generated.':e.message,reasons:['No mock result has been substituted for an unsuccessful real model call.'],next:'Check inputs and local API connection, then re-run.',review:false};log('Assessment stopped',e.message)}finally{busy=false;render()}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(busy){toast('Wait for completion or cancel the assessment first.');return}view=b.dataset.view;render()});render();
